// Turn-level counterfactual for the type_contract gate.
//
// PRE-REGISTERED before any run. Two pass-rate A/Bs have now returned nulls
// caused by non-occurrence, so this measures where the triggering condition is
// KNOWN to exist: all six lexical-smoke-gate-ab runs carry the defect (validated
// 6/6 by re-probing their reconstructed trees).
//
// Replays each run's recorded DONE turn with and without the gate's real bounce,
// generated by the real formatter from that run's own findings.
//
// PRIMARY: does the model emit a corrective edit to the flagged module?
// SECONDARY: does it stop re-asserting done?
// FALSIFIED IF: the gate arm re-asserts done as often as control, or edits at the
// same rate. Raw outputs are persisted so this is re-scorable without re-running.

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { prepareReplay, withSampleSeed } from "../../src/replay.js";
import { ModelClient } from "../../src/model.js";
import { actionGrammar } from "../../src/grammar.js";
import { typeContractSmokeWorkspace, formatTypeContractSmoke } from "../../src/logic/type-contract-smoke.js";

const ROOT = path.resolve(new URL("../..", import.meta.url).pathname);
const FIXTURE = path.join(ROOT, "gauntlet/fixtures/adapter-migration");
const TASK = JSON.parse(fs.readFileSync(path.join(FIXTURE, "task.json"), "utf8")).task;
const RUNS = path.join(ROOT, ".bantam/experiments/lexical-smoke-gate-ab/runs");
const SAMPLES = Number(process.argv[2] || 2);
const FLAGGED = /normalizeTags|normalizeHeaders|normalizePage|normalizeRetry/;

function specimens() {
  const out = [];
  const walk = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (/adapter-migration-run-.*\.json$/.test(e.name)) out.push(p);
    }
  };
  walk(RUNS);
  return out.sort();
}

// Rebuild the run's final tree so the bounce is generated from its OWN defect,
// exactly as the live gate would.
async function bounceFor(file) {
  const d = JSON.parse(fs.readFileSync(file, "utf8"));
  const diff = (d.finalDiff && (d.finalDiff.text ?? d.finalDiff)) || "";
  const ws = fs.mkdtempSync(path.join(os.tmpdir(), "tc-cf-"));
  try {
    fs.cpSync(path.join(FIXTURE, "repo"), ws, { recursive: true });
    if (String(diff).trim()) {
      fs.writeFileSync(path.join(ws, ".patch"), String(diff).endsWith("\n") ? diff : diff + "\n");
      execFileSync("git", ["init", "-q"], { cwd: ws });
      execFileSync("git", ["apply", "--whitespace=nowarn", ".patch"], { cwd: ws, stdio: ["ignore", "ignore", "pipe"] });
    }
    const findings = await typeContractSmokeWorkspace(ws, TASK);
    return { findings, text: formatTypeContractSmoke(findings) };
  } finally {
    fs.rmSync(ws, { recursive: true, force: true });
  }
}

function scoreOutput(text) {
  let a;
  try { a = JSON.parse(String(text).trim()); } catch { return "unparsed"; }
  if (a?.a === "done") return "re-done";
  const targets = [];
  if (Array.isArray(a?.edits)) for (const e of a.edits) targets.push({ p: e?.p, body: String(e?.new ?? "") });
  if (a?.a === "replace") targets.push({ p: a.p, body: String(a.new ?? "") });
  if (a?.a === "write_file") targets.push({ p: a.p, body: String(a.content ?? "") });
  if (!targets.length) return `investigated:${a?.a ?? "?"}`;
  const hit = targets.find((t) => FLAGGED.test(String(t.p ?? "")) || FLAGGED.test(t.body));
  if (!hit) return "edited-elsewhere";
  return /throw\s+new\s+TypeError|Array\.isArray|typeof\s+\w+\s*!==\s*["']string["']/.test(hit.body)
    ? "tightened" : "edited-not-tightened";
}

const client = new ModelClient({ apiUrl: "http://localhost:8085" });
async function ask(artifact, turn, inject, i) {
  const r = withSampleSeed(prepareReplay(artifact, turn, { inject }), i);
  const out = r.request ? await client.completeRequest(r.request)
    : await client.complete(r.prompt, { grammar: actionGrammar(), nPredict: 2048 });
  return String(out?.content ?? out ?? "");
}

const doneTurn = (d) => (d.turns ?? []).findIndex((t) => (t.parsedAction ?? {}).a === "done");
const tally = { control: {}, gate: {} };
const bump = (arm, k) => { tally[arm][k] = (tally[arm][k] ?? 0) + 1; };
const raw = [];

for (const file of specimens()) {
  const artifact = JSON.parse(fs.readFileSync(file, "utf8"));
  const turn = doneTurn(artifact);
  if (turn < 0) { console.log("skip (no done turn):", file); continue; }
  const { findings, text } = await bounceFor(file);
  const tag = file.split("/runs/")[1].split("/adapter")[0];
  if (!findings.length) { console.log(`skip (no defect): ${tag}`); continue; }

  for (let i = 0; i < SAMPLES; i++) {
    const cOut = await ask(artifact, turn, "", i);
    const c = scoreOutput(cOut);
    raw.push({ tag, sample: i, arm: "control", score: c, out: cOut });
    bump("control", c);
    console.log(`${tag} s${i} control -> ${c}`);
    const gOut = await ask(artifact, turn, text, i);
    const g = scoreOutput(gOut);
    raw.push({ tag, sample: i, arm: "gate", score: g, out: gOut });
    bump("gate", g);
    console.log(`${tag} s${i} gate    -> ${g}`);
  }
}

fs.writeFileSync(process.env.RAW_OUT || "/tmp/type-contract-cf.json", JSON.stringify(raw, null, 1));
console.log("\n=== TALLY ===");
for (const arm of ["control", "gate"]) console.log(arm.padEnd(8), JSON.stringify(tally[arm]));
const n = (arm) => Object.values(tally[arm]).reduce((a, b) => a + b, 0);
console.log(`\ncontrol tightened: ${tally.control.tightened ?? 0}/${n("control")}   re-done: ${tally.control["re-done"] ?? 0}/${n("control")}`);
console.log(`gate    tightened: ${tally.gate.tightened ?? 0}/${n("gate")}   re-done: ${tally.gate["re-done"] ?? 0}/${n("gate")}`);
